-- Historical sales from Sales_Categorized_Fixed.xlsx.
-- Generated source data is inserted below. Run once in Supabase SQL Editor.
-- Re-runs are idempotent by checkout_operation_id and transaction operation_id.
-- This imports sales history without changing present inventory quantities.
-- Payment method is unknown in the workbook and is stored as Unspecified.
-- All source dates are date-only; noon Asia/Manila is a placeholder time.
-- Omitted source rows: Nov 18-23 row 48 (no article or amount), row 87
-- (no quantity or amount). Source TOTAL rows are summaries, not sales.
begin;

create temp table _scf_source (
  sheet text not null, row_number integer not null, source_order text not null,
  date_serial integer not null, quantity numeric not null, unit text not null,
  article text not null, category text not null, amount numeric not null,
  primary key (sheet, row_number),
  check (quantity > 0 and amount >= 0)
) on commit drop;

insert into _scf_source
select sheet, row_number, source_order, date_serial, quantity, unit,
       article, category, amount
from jsonb_to_recordset($scf$
