$scf$::jsonb) as x(
  sheet text, row_number integer, source_order text, date_serial integer,
  quantity numeric, unit text, article text, category text, amount numeric
);

-- A multi-store database needs an explicit location. Set this UUID if needed.
create temp table _scf_config (location_id uuid not null) on commit drop;
insert into _scf_config
select id from public.locations
where id = coalesce(null::uuid, -- Replace null with the client's location UUID if there are multiple stores.
  case when (select count(*) from public.locations) = 1 then id end);

do $$
begin
  if (select count(*) from _scf_config) <> 1 then
    raise exception 'Select exactly one client location in _scf_config before import';
  end if;
  if not exists (
    select 1 from public.profiles p join _scf_config c on c.location_id = p.location_id
    where p.role = 'helper' and p.is_active
  ) then
    raise exception 'No active Supabase helper exists for the selected location';
  end if;
  if (select count(*) from _scf_source) <> 153 or
     (select count(distinct sheet || ':' || source_order) from _scf_source) <> 45 or
     (select sum(amount) from _scf_source) <> 96420 then
    raise exception 'Workbook source totals changed; review the import';
  end if;
end $$;

-- Historical-only catalog entries preserve the source article and unit without
-- guessing matches against the live inventory. They start inactive at zero stock.
with catalog as (
  select distinct s.article, s.unit, s.category, c.location_id,
    'sales-categorized-fixed:' || c.location_id::text || ':' ||
      md5(lower(s.article) || '|' || lower(s.unit) || '|' || lower(s.category)) as source_key
  from _scf_source s cross join _scf_config c
)
insert into public.products
  (sku, product_name, category, unit, product_price, product_quantity,
   location_id, is_active, create_operation_id, description)
select 'HIST-SCF-' || substr(md5(source_key), 1, 24), article, category, unit,
       0, 0, location_id, false, source_key,
       'Historical sales import; source workbook Sales_Categorized_Fixed.xlsx'
from catalog
on conflict (sku) do nothing;

do $$
begin
  if exists (
    select 1 from _scf_source s cross join _scf_config c
    where not exists (
      select 1 from public.products p
      where p.create_operation_id = 'sales-categorized-fixed:' || c.location_id::text || ':' ||
        md5(lower(s.article) || '|' || lower(s.unit) || '|' || lower(s.category))
        and p.location_id = c.location_id
    )
  ) then
    raise exception 'Historical product mapping failed';
  end if;
end $$;

create temp table _scf_mapped on commit drop as
select s.*, c.location_id, p.id as product_id,
       'sales-categorized-fixed:' || c.location_id::text || ':' ||
         md5(s.sheet || ':' || s.source_order) as operation_id,
       (date '1899-12-30' + s.date_serial + time '12:00') at time zone 'Asia/Manila' as sale_at
from _scf_source s cross join _scf_config c
join public.products p
  on p.create_operation_id = 'sales-categorized-fixed:' || c.location_id::text || ':' ||
       md5(lower(s.article) || '|' || lower(s.unit) || '|' || lower(s.category))
 and p.location_id = c.location_id;

do $$
begin
  if (select count(*) from _scf_mapped) <> 153 then
    raise exception 'Mapped line count does not match source';
  end if;
end $$;

with sale_orders as (
  select m.operation_id, m.location_id, min(m.sale_at) as sale_at,
    sum(m.amount) as total_amount,
    jsonb_agg(jsonb_build_object(
      'product_id', m.product_id, 'product_name', m.article,
      'quantity', m.quantity, 'unit', m.unit,
      'unit_price', round(m.amount / m.quantity, 2),
      'line_total', m.amount, 'source_sheet', m.sheet,
      'source_order', m.source_order, 'source_row', m.row_number
    ) order by m.row_number) as items
  from _scf_mapped m
  group by m.operation_id, m.location_id
)
insert into public.orders
  (status, items, location_id, created_at, updated_at, completed_at,
   assigned_at, prepared_at, total_amount, discount_amount, payment_mode,
   cash_given, change_amount, assigned_helper_id, assigned_helper_name,
   prepared_by_id, prepared_by_name, checkout_operation_id)
select 'completed', o.items, o.location_id, o.sale_at, o.sale_at, o.sale_at,
       o.sale_at, o.sale_at, o.total_amount, 0, 'Unspecified',
       null, null, h.id::text, h.name, h.id::text, h.name, o.operation_id
from sale_orders o
cross join lateral (
  select p.id, p.name from public.profiles p
  where p.location_id = o.location_id and p.role = 'helper' and p.is_active
  order by md5(o.operation_id || ':' || p.id::text) limit 1
) h
on conflict (checkout_operation_id) where checkout_operation_id is not null do nothing;

-- Checkout movement history is added for analytics. No stock balance is touched.
insert into public.transaction_history
  (created_at, product_id, transaction_type, quantity_change, new_quantity,
   location_id, note, operation_id, operation_scope)
select min(m.sale_at), m.product_id, 'checkout', -sum(m.quantity), null,
       m.location_id,
       'Historical sale import from Sales_Categorized_Fixed.xlsx; no stock adjustment',
       m.operation_id, 'historical_sales_import'
from _scf_mapped m
group by m.location_id, m.operation_id, m.product_id
on conflict (location_id, operation_id, product_id, transaction_type)
  where operation_id is not null do nothing;

do $$
begin
  if (select count(*) from public.orders o join _scf_config c on c.location_id = o.location_id
      where o.checkout_operation_id like 'sales-categorized-fixed:%') < 45 then
    raise exception 'Imported order count is incomplete';
  end if;
  raise notice 'Imported 45 orders, 153 complete lines, total PHP 96420';
end $$;
commit;
